package com.mps.availability.service;
import com.mps.audit.service.AuditService; import com.mps.auth.model.AppUser; import com.mps.auth.repository.AppUserRepository; import com.mps.auth.security.UserPrincipal; import com.mps.availability.dto.AvailabilityDtos.*; import com.mps.availability.model.*; import com.mps.availability.repository.AvailabilityEntryRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class AvailabilityService { private final AvailabilityEntryRepository repo; private final AppUserRepository users; private final AuditService audit;
 public AvailabilityService(AvailabilityEntryRepository r,AppUserRepository u,AuditService a){repo=r;users=u;audit=a;}
 @Transactional public AvailabilityView create(UserPrincipal p,CreateAvailabilityRequest req){if(req.startAt()==null||req.endAt()==null||!req.endAt().isAfter(req.startAt()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End time must be after start time."); AppUser user=users.findByIdAndOrganizationId(p.userId(),p.organizationId()).orElseThrow(); AvailabilityEntry e=repo.save(new AvailabilityEntry(user.getOrganization(),user,req.startAt(),req.endAt(),req.status(),req.notes())); audit.record(user.getOrganization(),p.userId(),"AVAILABILITY_CREATED","Availability",e.getId(),"SUCCESS",Map.of("status",req.status().name())); return view(e);}
 @Transactional(readOnly=true) public List<AvailabilityView> list(UserPrincipal p,Instant from,Instant to){if(!to.isAfter(from))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid range."); return repo.findAllByOrganizationIdAndUserIdAndStartAtLessThanAndEndAtGreaterThanOrderByStartAtAsc(p.organizationId(),p.userId(),to,from).stream().map(this::view).toList();}
 private AvailabilityView view(AvailabilityEntry e){return new AvailabilityView(e.getId(),e.getStartAt(),e.getEndAt(),e.getStatus(),e.getNotes());}
}
